public TrainingMetrics TrainAndEvaluate()
{
    var mlContext = new MLContext(seed: 42);

    var data = mlContext.Data.LoadFromTextFile<TicketInput>(
        _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

    // Featurize text columns and combine with Priority into a single Features vector
    var pipeline = mlContext.Transforms.Conversion
            .MapValueToKey("Label", nameof(TicketInput.Category))
        .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
        .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
        .Append(mlContext.Transforms.Concatenate("Features",
            "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
        .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
            labelColumnName: "Label", featureColumnName: "Features"))
        .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    // Use cross-validation for evaluation (better for small datasets)
    _logger.LogInformation("Cross-validating model...");
    var cvResults = mlContext.MulticlassClassification.CrossValidate(
        data, pipeline, numberOfFolds: 3, labelColumnName: "Label");

    var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
    var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
    var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);
    var avgLogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction);

    _logger.LogInformation(
        "Cross-validation — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}, LogLossReduction: {Reduction:F4}",
        avgMicro, avgMacro, avgLogLoss, avgLogLossReduction);

    // Train final model on full dataset
    var model = pipeline.Fit(data);
    mlContext.Model.Save(model, data.Schema, _modelPath);
    _logger.LogInformation("Model saved to {Path}", _modelPath);

    // Build per-category metrics from the best fold
    var bestFold = cvResults.OrderByDescending(r => r.Metrics.MicroAccuracy).First();
    var perCategory = bestFold.Metrics.PerClassLogLoss
        .Select((logLoss, i) => new CategoryMetric
        {
            Category = i < Labels.Length ? Labels[i] : $"Class{i}",
            Precision = safe(1.0 - logLoss),
            Recall = 0
        }).ToList();

    static double safe(double v) => double.IsFinite(v) ? v : 0;

    return new TrainingMetrics
    {
        MicroAccuracy = safe(avgMicro),
        MacroAccuracy = safe(avgMacro),
        LogLoss = safe(avgLogLoss),
        LogLossReduction = safe(avgLogLossReduction),
        PerCategory = perCategory
    };
}

